 "content": "from collections import Counter


def transform(grid):
    """Slide the non-background pattern next to the full 2-colored guide line."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    guide = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not guide:
        return out
    background = Counter(v for row in grid for v in row if v != 2).most_common(1)[0][0]
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, background)]
    if not obj:
        return out
    if len({r for r, _ in guide}) == 1:
        gr = guide[0][0]
        minr, maxr = min(r for r, _ in obj), max(r for r, _ in obj)
        if minr > gr:
            dr = gr + 1 - minr
        elif maxr < gr:
            dr = gr - 1 - maxr
        else:
            return out
        for r, c in obj:
            out[r][c] = background
        for r, c in obj:
            out[r + dr][c] = grid[r][c]
    elif len({c for _, c in guide}) == 1:
        gc = guide[0][1]
        minc, maxc = min(c for _, c in obj), max(c for _, c in obj)
        if minc > gc:
            dc = gc + 1 - minc
        elif maxc < gc:
            dc = gc - 1 - maxc
        else:
            return out
        for r, c in obj:
            out[r][c] = background
        for r, c in obj:
            out[r][c + dc] = grid[r][c]
    return out
